import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

// ------------------------------------------------------------------
// ActionPill container
// ------------------------------------------------------------------

const actionPillVariants = cva(
  ['flex items-center rounded-full', 'shadow-md overflow-hidden transition-all duration-300'],
  {
    variants: {
      size: {
        desktop: 'h-10',
        mobile: 'h-12',
      },
      variant: {
        accent: 'bg-[var(--color-accent-500)] text-[var(--color-accent-foreground-icon)]',
        surface: [
          'backdrop-blur-[16px]',
          'bg-[color-mix(in_srgb,var(--color-surface-light)_80%,transparent)]',
          'dark:bg-[color-mix(in_srgb,var(--color-surface-dark)_80%,transparent)]',
          'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
          'text-[var(--color-accent-500)]',
        ].join(' '),
      },
    },
    defaultVariants: {
      size: 'desktop',
      variant: 'accent',
    },
  }
)

export type ActionPillVariant = 'accent' | 'surface'

export interface ActionPillProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof actionPillVariants> {}

/**
 * Pill container for icon-only toolbar action buttons. Place one or more
 * `ActionPillButton` children inside.
 *
 * Size variants: `desktop` (h-10 / 40px, buttons w-10) and `mobile`
 * (h-12 / 48px, buttons w-12).
 *
 * Visual variants: `accent` (the primary pill -- accent bg, foreground-icon
 * color) and `surface` (secondary pill -- frosted surface bg + border with
 * accent-colored icons, same chrome as BottomNav / elevated toolbar panes).
 * Use `accent` for THE primary action group and `surface` for secondary
 * groups sitting next to it, so adjacent pills read as distinct groups
 * rather than one blob. Pass the same `variant` to the buttons inside.
 */
const ActionPill = React.forwardRef<HTMLDivElement, ActionPillProps>(
  ({ className, size, variant, ...props }, ref) => (
    <div
      ref={ref}
      className={cn(actionPillVariants({ size, variant }), className)}
      {...props}
    />
  )
)
ActionPill.displayName = 'ActionPill'

// ------------------------------------------------------------------
// Shared button hover/active treatment per pill variant
// ------------------------------------------------------------------

const buttonVariantClasses: Record<ActionPillVariant, string> = {
  accent:
    'hover:bg-[var(--color-accent-foreground-icon-10)] active:bg-[var(--color-accent-foreground-icon-20)]',
  surface:
    'hover:bg-[var(--color-warm-100)] dark:hover:bg-[var(--color-neutral-800)] active:bg-[var(--color-warm-200)] dark:active:bg-[var(--color-neutral-700)] disabled:opacity-50 disabled:pointer-events-none',
}

// ------------------------------------------------------------------
// ActionPillButton
// ------------------------------------------------------------------

export interface ActionPillButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** When false the button collapses to w-0 and becomes inert. */
  visible?: boolean
  /**
   * ReactNode icon to render. The DS avoids bundling an icon library so the
   * caller passes the icon element directly (e.g. `<Plus size={20} weight="bold" />`).
   */
  icon: React.ReactNode
  /** aria-label and title for the button -- required for accessibility. */
  label: string
  /** Size variant inherited from the parent ActionPill (pass through explicitly). */
  size?: 'desktop' | 'mobile'
  /** Visual variant inherited from the parent ActionPill (pass through explicitly). */
  variant?: ActionPillVariant
}

/**
 * Icon-only button for use inside `ActionPill`.
 *
 * When `visible` is `false` the button collapses to zero width, opacity 0, and
 * `pointer-events-none` with `tabIndex=-1` so it is completely inert. This is
 * the morphing-pill pattern: the pill container shrinks/grows as context-
 * dependent buttons are shown or hidden.
 *
 * `label` is applied as both `aria-label` and `title` (tooltip on hover).
 */
const ActionPillButton = React.forwardRef<HTMLButtonElement, ActionPillButtonProps>(
  ({ visible = true, icon, label, size = 'desktop', variant = 'accent', className, ...props }, ref) => {
    const dim = size === 'mobile' ? 'w-12 h-12' : 'w-10 h-10'
    return (
      <button
        ref={ref}
        aria-label={label}
        title={label}
        tabIndex={visible ? 0 : -1}
        className={cn(
          'wj-focus-ring flex items-center justify-center',
          buttonVariantClasses[variant],
          'transition-all duration-300',
          visible ? `${dim} opacity-100` : 'w-0 opacity-0 pointer-events-none',
          className
        )}
        {...props}
      >
        {icon}
      </button>
    )
  }
)
ActionPillButton.displayName = 'ActionPillButton'

// ------------------------------------------------------------------
// ActionPillStaticButton -- always-visible button (no collapse)
// ------------------------------------------------------------------

export interface ActionPillStaticButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon: React.ReactNode
  label: string
  size?: 'desktop' | 'mobile'
  variant?: ActionPillVariant
}

/**
 * Always-visible button for use inside `ActionPill`. Use for actions that are
 * never context-dependent (e.g., the "+" create button). Contrast with
 * `ActionPillButton` which can be hidden.
 */
const ActionPillStaticButton = React.forwardRef<HTMLButtonElement, ActionPillStaticButtonProps>(
  ({ icon, label, size = 'desktop', variant = 'accent', className, ...props }, ref) => {
    const dim = size === 'mobile' ? 'w-12 h-12' : 'w-10 h-10'
    return (
      <button
        ref={ref}
        aria-label={label}
        title={label}
        className={cn(
          'wj-focus-ring flex items-center justify-center',
          dim,
          buttonVariantClasses[variant],
          'transition-colors',
          className
        )}
        {...props}
      >
        {icon}
      </button>
    )
  }
)
ActionPillStaticButton.displayName = 'ActionPillStaticButton'

export { ActionPill, ActionPillButton, ActionPillStaticButton, actionPillVariants }
